TLM.f("Tempora/Quadp3-1",{"officium":"Feria II infra Hebdomadam Quinquagesimæ","rule":["vide Quadp3-0","no Gloria","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp3-0","from":{"Introitus":"Tempora/Quadp3-0","Oratio":"Tempora/Quadp3-0","Lectio":"Tempora/Quadp3-0","GradualeF":"Tempora/Quadp3-0","Evangelium":"Tempora/Quadp3-0","Offertorium":"Tempora/Quadp3-0","Secreta":"Tempora/Quadp3-0","Communio":"Tempora/Quadp3-0","Postcommunio":"Tempora/Quadp3-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 30:3-4"},{"k":"text","la":"Esto mihi in Deum protectórem, et in locum refúgii, ut salvum me fácias: quóniam firmaméntum meum et refúgium meum es tu: et propter nomen tuum dux mihi eris, et enútries me."},{"k":"ref","la":"Ps 30:2"},{"k":"text","la":"In te, Dómine, sperávi, non confúndar in ætérnum: in justítia tua líbera me et éripe me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Esto mihi in Deum protectórem, et in locum refúgii, ut salvum me fácias: quóniam firmaméntum meum et refúgium meum es tu: et propter nomen tuum dux mihi eris, et enútries me."}],"Oratio":[{"k":"text","la":"Preces nostras, quǽsumus, Dómine, cleménter exáudi: atque, a peccatórum vínculis absolútos, ab omni nos adversitáte custódi."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"1 Cor 13:1-13"},{"k":"text","la":"Fratres: Si linguis hóminum loquar et Angelórum, caritátem autem non hábeam, factus sum velut æs sonans aut cýmbalum tínniens. Et si habúero prophetíam, et nóverim mystéria ómnia et omnem sciéntiam: et si habúero omnem fidem, ita ut montes tránsferam, caritátem autem non habúero, nihil sum. Et si distribúero in cibos páuperum omnes facultátes meas, et si tradídero corpus meum, ita ut árdeam, caritátem autem non habuero, nihil mihi prodest. Cáritas patiens est, benígna est: cáritas non æmulátur, non agit pérperam, non inflátur, non est ambitiósa, non quærit quæ sua sunt, non irritátur, non cógitat malum, non gaudet super iniquitáte, congáudet autem veritáti: ómnia suffert, ómnia credit, ómnia sperat, ómnia sústinet. Cáritas numquam éxcidit: sive prophétiæ evacuabúntur, sive linguæ cessábunt, sive sciéntia destruétur. Ex parte enim cognóscimus, et ex parte prophetámus. Cum autem vénerit quod perféctum est, evacuábitur quod ex parte est. Cum essem párvulus, loquébar ut párvulus, sapiébam ut párvulus, cogitábam ut párvulus. Quando autem factus sum vir, evacuávi quæ erant párvuli. Vidémus nunc per spéculum in ænígmate: tunc autem fácie ad fáciem. Nunc cognósco ex parte: tunc autem cognóscam, sicut et cógnitus sum. Nunc autem manent fides, spes, cáritas, tria hæc: major autem horum est cáritas."}],"Graduale":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 18:31-43"},{"k":"text","la":"In illo témpore: Assúmpsit Jesus duódecim, et ait illis: Ecce, ascéndimus Jerosólymam, et consummabúntur ómnia, quæ scripta sunt per Prophétas de Fílio hominis. Tradétur enim Géntibus, et illudétur, et flagellábitur, et conspuétur: et postquam flagelláverint, occídent eum, et tértia die resúrget. Et ipsi nihil horum intellexérunt, et erat verbum istud abscónditum ab eis, et non intellegébant quæ dicebántur. Factum est autem, cum appropinquáret Jéricho, cæcus quidam sedébat secus viam, mendícans. Et cum audíret turbam prætereúntem, interrogábat, quid hoc esset. Dixérunt autem ei, quod Jesus Nazarénus transíret. Et clamávit, dicens: Jesu, fili David, miserére mei. Et qui præíbant, increpábant eum, ut tacéret. Ipse vero multo magis clamábat: Fili David, miserére mei. Stans autem Jesus, jussit illum addúci ad se. Et cum appropinquásset, interrogávit illum, dicens: Quid tibi vis fáciam? At ille dixit: Dómine, ut vídeam. Et Jesus dixit illi: Réspice, fides tua te salvum fecit. Et conféstim vidit, et sequebátur illum, magníficans Deum. Et omnis plebs ut vidit, dedit laudem Deo."}],"Offertorium":[{"k":"ref","la":"Ps 118:12-13"},{"k":"text","la":"Benedíctus es, Dómine, doce me justificatiónes tuas: in lábiis meis pronuntiávi ómnia judícia oris tui."}],"Secreta":[{"k":"text","la":"Hæc hóstia, Dómine, quǽsumus, emúndet nostra delícta: et, ad sacrifícium celebrándum, subditórum tibi córpora mentésque sanctíficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 77:29-30"},{"k":"text","la":"Manducavérunt, et saturári sunt nimis, et desidérium eórum áttulit eis Dóminus: non sunt fraudáti a desidério suo."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, qui coeléstia aliménta percépimus, per hæc contra ómnia adversa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fbcb6a6346eeacf8":{"t":"Ps 30, 3-4, Ps 30, 2\n(Ps 30, 3-4) Budi mi, Bože, zaštitnik i utočište i spasi me, jer ti si moja jakost i moja tvrđa. Zbog imena svoga vodi me i hrani me. (Ps 30, 2) U tebe se, Gospodine, uzdam, ne daj da se razočaram ikada. U svojoj pravednosti izbavi me i spasi me.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 30, 3-4) Budi mi, Bože, zaštitnik i utočište i spasi me, jer ti si moja jakost i moja tvrđa. Zbog imena svoga vodi me i hrani me."},"15c884751338ceb0":{"t":"<i>Pomolimo se</i>.\nMolitve naše molimo, Gospodine, milostivo usliši i pošto nas odriješiš od grijeha, od svake nas nesreće čuvaj.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"ac0362599d39dab7":{"t":"1 Kor 13, 1-13\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Kad bih govorio sve ljudske i anđeoske jezike, a ljubavi ne bih imao, bio bih kao trublja ili praporac što zveči. I kad bih imao dar proroštva i razumio sve tajne i sve znanosti, i kad bih imao jaku vjeru da bih mogao premještati brda, a ljubavi ne bih imao, bio bih ništa. I kad bih sav svoj imetak razdijelio siromasima i svoje tijelo predao da se sažeže, a ljubavi ne bih imao, ništa mi ne bi koristilo. – Ljubav je strpljiva, ljubav je dobrostiva, ljubav ne zavidi, ne hvali se, ne uznosi se, ne teži za čašću, ne traži svoje, ne uznemiruje se, ne smišlja zla, ne veseli se nepravdi, a raduje se istini. Sve podnosi, sve vjeruje, svemu se nada, sve trpi. – Ljubav nikad ne prestaje, a proroštva će prestati, jezici će umuknuti, znanja će nestati, jer znamo i prorokujemo nepotpuno. A kada dođe ono što je savršeno, prestat će ono što je nepotpuno. Kad sam bio dijete, govorio sam kao dijete, osjećao sam kao dijete, mislio sam kao dijete. A kad sam odrastao, odbacio sam ono što je bilo djetinje. Sada gledamo kao u ogledalu, nejasno, a tada ćemo gledati neposredno. Sada spoznajem nepotpuno, a onda ću spoznati kao što sam i spoznat. Sad ostaje ovo troje: vjera, ufanje i ljubav, ali najveća je među njima ljubav."},"8aa6be6c4a2ef63d":{"t":"Ps 76, 15-16\nTi si Bog i samo ti činiš čudesa. Objavio si narodima svoju moć. Desnicom svojom izbavio si svoj narod, sinove Izraelove i Josipove."},"271b75835ce4e136":{"t":"Luc 18, 31-43\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Uze Isus sa sobom dvanaestoricu i reče im: »Evo idemo u Jeruzalem, i izvršit će se sve što su proroci napisali o Sinu Čovječjemu: Bit će predan poganima koji će ga izrugati, bičevati i popljuvati. A kad ga izbičuju, ubit će ga. Ali će treći dan uskrsnuti.« A oni od toga ništa nisu razumjeli. Taj im je govor bio neshvatljiv, te nisu razumjeli što im je govorio. – Kad je Isus bio blizu Jerihona, sjedio je kraj puta neki slijepac i prosio. Kad začuje kako prolazi narod, upita: »Što je to?« Odgovore mu da prolazi Isus Nazarećanin. On tada počne vikati: »Isuse, sine Davidov, smiluj mi se!« Oni koji su išli sprijeda, opominjali su ga neka šuti. Ali je on još jače vikao: »Sine Davidov, smiluj mi se!« Isus se zaustavi, zapovjedi da dovedu slijepca. A kad mu se približio, upita ga Isus: »Što hoćeš da ti učinim« On odgovori: »Gospodine, da progledam.« Isus mu reče: »Progledaj, vjera te je tvoja spasila.« On odmah progleda i pođe za njim veličajući Boga. I videći to sav je narod hvalio Boga.","v":"naslov evanđelja"},"47e5655797e3dca8":{"t":"Ps 118, 12-13\nBlagoslovljen si, Gospodine, nauči me svojim naredbama. Svojim usnama naviještam sve odluke tvojih usta."},"fbb53f48d9c24f02":{"t":"Molimo, Gospodine, da ovaj žrtveni dar izbriše naša zlodjela te da dušu i tijelo tvojih podložnika posveti za svetkovanje žrtve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"1ec2d48acd9247f9":{"t":"Ps 77, 29-30\nJeli su i obilno se nasitili, njihovu je želju ispunio Gospodin. Nisu se razočarali u svojoj čežnji."},"527356d665aab3ba":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas nebeska hrana koju smo primili utvrdi protiv svih nesreća.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
